  function gmFilter(md) {
    var out = [];
    md.split("\n").forEach(function (ln) {
      if (ln.indexOf("🔒") < 0) { out.push(ln); return; }
      if (OWNER) { out.push(ln.replace(/🔒\s*/g, "🔒 ")); return; }
      if (/^\s*\|/.test(ln)) { out.push(ln.split("|").map(function (c) { return c.indexOf("🔒") >= 0 ? " " : c; }).join("|")); return; }
      var cut = ln.slice(0, ln.indexOf("🔒")).replace(/\s+$/, "");
      if (/^\s*(#+|[-*>]|\d+\.)?\s*(\d+-\d+\.)?\s*(\*\*[^*]*\*\*)?\s*[:：—-]?\s*$/.test(cut)) return;
      out.push(cut);
    });
    return out.join("\n");
  }
